/*
 * A121040  Multiples of 20 containing a 20 in their decimal representation.
 * https://oeis.org/A121040
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 4, u16 n <= 44, u32 n <= 44, u64 n <= 44, u128 n <= 44,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  This function returns the n‑th number that is a multiple of 20
 *  and whose decimal representation contains the substring “20”.
 *  The sequence is generated by a simple brute‑force search; no
 *  caching or allocation is required.
 */

#include <stdbool.h>

/* Return true if x contains the decimal substring "20".  */
static bool contains20(seq_t x)
{
    seq_t prev = (seq_t)0;            /* previous digit (sentinel) */
    while (x != (seq_t)0) {
        seq_t d = x % (seq_t)10;
        if (d == (seq_t)2 && prev == (seq_t)0) {
            return true;
        }
        prev = d;
        x = x / (seq_t)10;
    }
    return false;
}

seq_t a(idx_t n)
{
    if (n < (idx_t)1) {
        return (seq_t)0;             /* defined only for n >= 1 */
    }

    idx_t count = 0;                 /* how many terms found so far */
    seq_t  m;                        /* current multiple of 20 */

    for (idx_t k = (idx_t)1; ; ++k) {
        m = (seq_t)(k * (idx_t)20);  /* m = 20 * k */
        if (contains20(m)) {
            ++count;
            if (count == n) {
                return m;
            }
        }
    }
}
